fn restore_capture(records: &str, source: &str, current: &str) -> Option<String> {
    let records: serde_json::Value = serde_json::from_str(records).unwrap();
    assert_eq!(
        records["schema"],
        "semaprax.browser-complete-source-bridge.v1"
    );
    let row = records["rows"]
        .as_array()
        .unwrap()
        .iter()
        .find(|row| row["source"] == source)?;
    assert_eq!(sha(current), row["current_sha256"]);
    let mut previous = current.to_owned();
    for edit in row["inverse"].as_array().unwrap().iter().rev() {
        let new = edit["current"].as_str().unwrap();
        assert!(!new.is_empty());
        assert_eq!(previous.matches(new).count(), 1);
        previous = previous.replacen(new, edit["previous"].as_str().unwrap(), 1);
    }
    assert_eq!(sha(&previous), row["previous_sha256"]);
    Some(previous)
}

fn prior_source<'a>(source: &str, current: &'a str) -> Cow<'a, str> {
    let data =
        include_str!("../../../docs/evidence/browser-capture-3d81-20261024/source-inverses.json");
    assert!(data.len() <= 262_144);
    let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR"));
    assert_eq!(
        std::fs::read_to_string(
            root.join("docs/evidence/browser-capture-3d81-20261024/source-inverses.json")
        )
        .unwrap(),
        data
    );
    let records: serde_json::Value = serde_json::from_str(data).unwrap();
    assert_eq!(
        records["schema"],
        "semaprax.browser-complete-source-bridge.v1"
    );
    assert_eq!(records["rows"].as_array().unwrap().len(), 3);
    assert_eq!(records["successor_rows"].as_array().unwrap().len(), 1);
    assert_eq!(
        records["successor_rows"][0]["source"],
        "tests/wasm/scalar_browser_ci_contract/current_profiles3d81.rs"
    );
    let rows: Vec<_> = records["rows"]
        .as_array()
        .unwrap()
        .iter()
        .chain(records["successor_rows"].as_array().unwrap().iter())
        .filter(|row| row["source"] == source)
        .collect();
    assert_eq!(rows.len(), 1);
    let row = rows[0];
    // New acquisition extends the original inverse without rewriting any
    // sealed row. The existing complete-source hash, physical read, unique
    // inverse and full original byte equality below remain authoritative.
    let mut latest_row;
    let row = if let Some(latest) = records["latest_rows"].as_array().and_then(|rows| {
        let mut found = rows.iter().filter(|r| r["source"] == source);
        let first = found.next();
        assert!(
            found.next().is_none(),
            "one complete latest source extension"
        );
        first
    }) {
        latest_row = row.clone();
        latest_row["current_sha256"] = latest["current_sha256"].clone();
        latest_row["inverse"]
            .as_array_mut()
            .unwrap()
            .extend(latest["inverse"].as_array().unwrap().iter().cloned());
        &latest_row
    } else {
        row
    };
    let previous = before(source);
    assert_eq!(sha(previous), row["previous_sha256"]);
    // This exact historical input was already accepted by the retained receiver.
    if current == previous {
        return Cow::Borrowed(current);
    }
    assert_eq!(current, compiled(source));
    assert_eq!(current, std::fs::read_to_string(root.join(source)).unwrap());
    let mut restored =
        before_current_capture(source, current).unwrap_or_else(|| current.to_owned());
    assert_eq!(sha(&restored), row["current_sha256"]);
    for edit in row["inverse"].as_array().unwrap().iter().rev() {
        let new = edit["current"].as_str().unwrap();
        assert!(!new.is_empty());
        assert_eq!(
            restored.matches(new).count(),
            1,
            "unique whole-source inverse"
        );
        restored = restored.replacen(new, edit["previous"].as_str().unwrap(), 1);
    }
    assert_eq!(
        restored, previous,
        "entire original receiver or runner retained"
    );
    Cow::Owned(restored)
}

